import {attachmentList} from './attachments.mjs';
import {shootingActions} from './shooting-contract.mjs';
import {shootingLabels} from './shooting-editors.mjs';
import {calendarGroups,publicationStage,weekDates} from './business-model.mjs';
import {chinaDate,taskProgress,metricValue} from './cloud-api.mjs';
export const businessPages=new Set(['products','shooting','calendar','publishing','product-tests']);
export function createBusinessViews({api,h,heading,showPanel,source,localTime,writable=false,getRole=()=>null}){
 const $=s=>document.querySelector(s);
 const blank=(title,desc)=>`<div class="empty"><h3>${h(title)}</h3><p>${h(desc)}</p></div>`;
 const badge=(label,tone='')=>`<span class="stage-pill ${tone}">${h(label)}</span>`;
 const count=value=>value===null||value===undefined?'未提供':h(value);
 const detailHead=title=>`<div class="dialog-header"><h2>${h(title)}</h2><button class="icon-button" data-panel-close aria-label="关闭详情">×</button></div>`;
 const disabled=(label)=>`<button class="secondary" disabled title="${writable?'这项操作接入后开放':'当前云端为只读预览'}">${h(label)}</button>`;
 const pageHeader=(title,desc)=>heading(title,desc);
 const keyValues=(pairs)=>`<dl class="record-facts">${pairs.map(([label,value])=>`<div><dt>${h(label)}</dt><dd>${h(value??'未填写')}</dd></div>`).join('')}</dl>`;
 const taskLink=t=>`<button class="linked-record" data-live-task="${h(t.id)}"><span><b>${h(t.title)}</b><small>${h(t.assignee||'未提供负责人')} · ${h(t.accountName||'无需账号')}</small></span><span>${h(taskProgress(t))} →</span></button>`;
 let currentWeek=chinaDate(),canEditProducts=false;
 async function productDetail(id){
  await showPanel('产品资料',async signal=>{
   const p=await api.product(id,signal);
   return detailHead(p.name)+`<div class="detail-meta">${badge(p.active?'在用':'已停用',p.active?'green':'')}<span>${h(p.storeName||'未关联店铺')}</span></div><div class="action-row">${canEditProducts?`<button class="secondary" data-edit-product="${h(p.id)}">编辑产品</button>`:disabled('编辑产品')}${disabled('安排内容测试')}</div><div class="detail-content"><h3>产品说明</h3><p class="preserve-text">${h(p.notes||'还没有产品说明。')}</p><h3>工作阶段</h3><div class="stage-track">${p.stages.map((s,i)=>`<span><i>${i+1}</i>${h(s.name)}</span>`).join('')||'<span class="muted">暂无阶段</span>'}</div><h3>相关执行事项 · ${p.tasks.length}</h3>${p.tasks.map(taskLink).join('')||blank('还没有执行安排','后续在测品或内容安排中引用这份产品档案。')}<h3>产品复盘</h3>${p.reviews.map(r=>`<article class="observation"><b>${h(r.decision)}</b><p class="preserve-text">${h(r.reason||'暂无说明')}</p><small class="muted">${h(localTime(r.createdAt))}</small></article>`).join('')||'<p class="muted">暂无产品复盘记录。</p>'}</div>`;
  });
 }
 async function shootingDetail(id){
  await showPanel('拍摄需求',async signal=>{
   const r=await api.shootingDetail(id,signal),active=writable&&!r.archived&&r.status!=='已完成';
   const actionButton=action=>`<button class="${action==='reshoot'?'secondary':'primary'}" data-shoot-action="${action}" data-shoot-id="${h(r.id)}">${h(shootingLabels[action])}</button>`;
   const uploadButton=(label,itemId)=>`<button class="secondary" data-media-upload="shooting" data-media-owner="${h(r.id)}" ${itemId?`data-media-item="${h(itemId)}"`:''}>${h(label)}</button>`;
   const lines=value=>Array.isArray(value)?value.join('\n'):value||'';
   return detailHead(r.title)+`<div class="detail-meta">${badge(r.status,r.status==='已完成'?'green':'amber')}<span>${h(r.archived?'已归档':'在用需求')}</span><span>版本 ${h(r.version)}</span></div>${keyValues([['产品',r.productName||r.productDescription],['负责人',r.assigneeName||'未派发'],['交付日期',r.dueOn||'未排期'],['交付位置',r.nasPath||'未填写']])}<div class="action-row"><button class="secondary" data-open-samples="${h(r.id)}">样品借用与归还</button><button class="secondary" data-open-equipment="${h(r.id)}">设备借用与归还</button>${active?`<button class="secondary" data-edit-shooting="${h(r.id)}">编辑需求</button>`:''}${writable?shootingActions(r,getRole()).map(actionButton).join(''):''}${writable&&getRole()==='admin'?`<button class="text-button" data-archive-shooting="${h(r.id)}" data-shoot-archived="${r.archived?'false':'true'}">${r.archived?'恢复需求':'归档需求'}</button>`:''}</div><div class="detail-content"><h3>拍摄要求</h3><p class="preserve-text">${h(r.summary||'未填写总体要求')}</p><h3>拍摄清单 · ${r.visibleItems.filter(i=>i.completed).length} / ${r.visibleItems.length}</h3>${r.visibleItems.map((item,index)=>`<article class="shoot-item"><div class="shoot-item-title">${active?`<button class="item-check ${item.completed?'checked':''}" data-shoot-item="${h(item.id)}" data-shoot-id="${h(r.id)}" data-shoot-version="${r.version}" data-item-completed="${item.completed?'false':'true'}" aria-label="${h(item.title)}：${item.completed?'标记未完成':'标记完成'}">${item.completed?'✓':index+1}</button>`:`<span class="item-check ${item.completed?'checked':''}">${item.completed?'✓':index+1}</span>`}<b>${h(item.title)}</b>${badge(item.kind==='video'?'视频':item.kind==='image'?'图片':item.kind||'类型未提供')}</div><p class="preserve-text">${h(lines(item.requirements)||'暂无具体要求')}</p>${lines(item.references)?`<p class="muted preserve-text">参考：${h(lines(item.references))}</p>`:''}${item.materialId?`<button class="text-button" data-live-material="${h(item.materialId)}">查看关联素材 →</button>`:''}${attachmentList(h,'shooting',r.id,r.visibleAssets.filter(a=>a.itemId===item.id))}${active?uploadButton('添加参考图片',item.id):''}</article>`).join('')||blank('尚无拍摄项','需求保留原记录，未自动生成拍摄项。')}<h3>交付文件</h3>${attachmentList(h,'shooting',r.id,r.visibleAssets.filter(a=>a.kind==='delivery'))}${active?uploadButton('＋ 上传交付文件'):''}<h3>补拍反馈</h3><p class="preserve-text">${h(r.feedback||'暂无补拍反馈')}</p>${r.lastCompletedAt?`<p class="muted">最近确认完成：${h(localTime(r.lastCompletedAt))}</p>`:''}<div class="action-row">${r.taskId&&r.assigneeId&&(getRole()==='admin'||r.assignedToMe)?`<button class="secondary" data-live-task="${h(r.taskId)}">查看关联事项</button>`:''}</div></div>`;
  });
 }
 document.addEventListener('click',e=>{
  const p=e.target.closest('[data-product-detail]'),s=e.target.closest('[data-shoot-detail]'),close=e.target.closest('[data-panel-close]');
  if(p)productDetail(p.dataset.productDetail);if(s)shootingDetail(s.dataset.shootDetail);if(close)$('#cloud-detail').close();
 });
 function catalog(rows){
  $('#main').innerHTML=pageHeader('产品管理','一份产品档案，关联素材、拍摄和测试。')+`<section class="summary-strip"><div><b>${rows.filter(p=>p.active).length}</b><span>在用产品</span></div><div><b>${rows.filter(p=>!p.active).length}</b><span>已停用</span></div><div><b>${new Set(rows.map(p=>p.storeName).filter(Boolean)).size}</b><span>已关联店铺</span></div></section><section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找产品<input id="product-query" type="search" placeholder="产品名称、店铺或说明"></label><label>查看范围<select id="product-active"><option value="active">在用产品</option><option value="all">全部产品</option><option value="inactive">已停用</option></select></label>${canEditProducts?'<button class="primary" data-edit-product="">＋ 新建产品</button>':disabled('＋ 新建产品')}</div><div class="catalog-grid" id="product-grid"></div><div class="module-foot">产品资料在这里集中维护，测试安排使用同一份产品档案。</div></section>`;
  const filter=()=>{const q=$('#product-query').value.trim().toLowerCase(),active=$('#product-active').value;const items=rows.filter(p=>(active==='all'||p.active===(active==='active'))&&[p.name,p.notes,p.storeName].join(' ').toLowerCase().includes(q));$('#product-grid').innerHTML=items.map(p=>`<article class="product-card"><div class="product-art" aria-hidden="true">${h(p.name.slice(0,1))}<span>PRODUCT</span></div><div class="product-card-body"><div class="material-card-top">${badge(p.active?'在用':'已停用',p.active?'green':'')}<span class="muted">${h(p.storeName||'未关联店铺')}</span></div><button class="material-title" data-product-detail="${h(p.id)}">${h(p.name)}</button><p class="material-excerpt">${h(p.notes||'暂无产品说明')}</p><div class="material-card-foot"><span>统一产品档案</span><button data-product-detail="${h(p.id)}">查看资料 →</button></div></div></article>`).join('')||blank('没有符合条件的产品','可以调整搜索和查看范围。');};$('#product-query').oninput=filter;$('#product-active').onchange=filter;filter();
 }
 function shooting(rows){
  $('#main').innerHTML=pageHeader('素材拍摄','从拍摄要求到交付反馈，把每一项做好。')+`<section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找拍摄需求<input id="shoot-query" type="search" placeholder="需求、产品或负责人"></label><label>拍摄状态<select id="shoot-status"><option value="all">全部状态</option>${[...new Set(rows.map(r=>r.status))].map(s=>`<option>${h(s)}</option>`).join('')}</select></label><label>范围<select id="shoot-archive"><option value="active">在用需求</option><option value="archived">已归档</option><option value="all">全部需求</option></select></label><button class="secondary" data-open-samples="">样品借用与归还</button><button class="secondary" data-open-equipment="">设备借用与归还</button>${writable?'<button class="primary" data-edit-shooting="">＋ 新建拍摄</button>':disabled('＋ 新建拍摄')}</div><div id="shoot-list"></div><div class="module-foot">每个需求关联原有执行事项，拍摄进度和交付使用同一记录。</div></section>`;
  const filter=()=>{const q=$('#shoot-query').value.trim().toLowerCase(),status=$('#shoot-status').value,archive=$('#shoot-archive').value;const items=rows.filter(r=>(status==='all'||r.status===status)&&(archive==='all'||r.archived===(archive==='archived'))&&[r.title,r.productName,r.productDescription,r.assigneeName].join(' ').toLowerCase().includes(q));$('#shoot-list').innerHTML=items.map(r=>`<button class="shoot-card" data-shoot-detail="${h(r.id)}"><div class="shoot-card-icon">▧</div><div class="shoot-card-main"><b>${h(r.title)}</b><p>${h(r.productName||r.productDescription||'未指定产品')}</p><small>${h(r.assigneeName||'未派发')} <span>·</span> ${h(r.dueOn?'交付 '+r.dueOn:'未设置交付日期')}</small></div><div class="shoot-progress"><div><span style="width:${r.visibleItems.length?Math.round(r.visibleItems.filter(i=>i.completed).length/r.visibleItems.length*100):0}%"></span></div><small>${r.visibleItems.filter(i=>i.completed).length} / ${r.visibleItems.length} 项</small></div>${badge(r.status,r.status==='已完成'?'green':'amber')}<span class="task-arrow">›</span></button>`).join('')||blank('暂无符合条件的拍摄需求','可以切换状态或查看归档需求。');};$('#shoot-query').oninput=filter;$('#shoot-status').onchange=filter;$('#shoot-archive').onchange=filter;filter();
 }
 function calendar(rows,user){
  $('#main').innerHTML=pageHeader('内容编排',`${user.role==='admin'?'团队':'本人'}执行事项的周安排，未排期事项单独保留。`)+`<div class="calendar-toolbar"><div class="date-control"><button id="previous-week" aria-label="前一周">‹</button><b id="week-caption"></b><button id="next-week" aria-label="后一周">›</button></div><button class="text-button" id="this-week">本周</button><label class="module-search"><input id="calendar-query" type="search" placeholder="搜索事项、账号或负责人" aria-label="搜索排期"></label></div><section class="week-board" id="week-board"></section><section class="work-panel unplanned-panel"><div class="panel-head"><h2>未排期事项 <span id="unplanned-count" class="muted"></span></h2></div><div id="unplanned-items"></div></section>`;
  const render=()=>{const q=$('#calendar-query').value.trim().toLowerCase();const filtered=rows.filter(t=>[t.title,t.accountName,t.assignee].join(' ').toLowerCase().includes(q));const model=calendarGroups(filtered,currentWeek),today=chinaDate();$('#week-caption').textContent=model.days[0].date+' — '+model.days[6].date;const card=t=>`<button class="calendar-item" data-live-task="${h(t.id)}"><b>${h(t.title)}</b><span>${h(t.accountName||'无需账号')}</span><small>${h(t.assignee||'负责人未提供')}</small>${t.completedAt?'<i>已完成</i>':''}</button>`;$('#week-board').innerHTML=model.days.map((day,i)=>`<section class="week-day ${day.date===today?'today':''}"><div class="week-day-head"><b>周${['一','二','三','四','五','六','日'][i]}</b><span>${day.date.slice(5).replace('-',' / ')}</span><small>${day.items.length} 件</small></div><div class="week-items">${day.items.map(card).join('')||'<p class="muted">暂无安排</p>'}</div></section>`).join('');$('#unplanned-count').textContent=model.unplanned.length+' 件';$('#unplanned-items').innerHTML=model.unplanned.map(taskLink).join('')||'<p class="muted">当前没有未排期事项。</p>';};
  const move=n=>{const d=new Date(currentWeek+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);currentWeek=d.toISOString().slice(0,10);render();};$('#previous-week').onclick=()=>move(-7);$('#next-week').onclick=()=>move(7);$('#this-week').onclick=()=>{currentWeek=chinaDate();render();};$('#calendar-query').oninput=render;render();
 }
 function publishing(rows){
  const tasks=rows.filter(t=>t.kind==='publication');
  $('#main').innerHTML=pageHeader('发布管理与数据回填','查看发布进度，进入原事项记录内容与多次观察。')+`<section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找发布事项<input id="publish-query" type="search" placeholder="事项、账号或负责人"></label><label>当前工作<select id="publish-scope"><option value="all">全部发布事项</option><option value="publish">仍需发布</option><option value="refill">仍需回填</option><option value="filled">已回填</option><option value="concluded">已结束</option></select></label></div><div id="publishing-list"></div><div class="module-foot">同一事项可能既需要继续发布，也有已发布内容等待回填；观察记录保留各自时间。</div></section>`;
  const render=()=>{const q=$('#publish-query').value.trim().toLowerCase(),scope=$('#publish-scope').value;const list=tasks.filter(t=>{const progress=publicationStage(t);return [t.title,t.accountName,t.assignee].join(' ').toLowerCase().includes(q)&&(scope==='all'||scope==='publish'&&t.experimentStatus!=='concluded'&&progress.needsPublishing||scope==='refill'&&t.experimentStatus!=='concluded'&&progress.needsRefill||scope==='filled'&&progress.hasRefills||scope==='concluded'&&t.experimentStatus==='concluded');});$('#publishing-list').innerHTML=list.map(t=>{const p=publicationStage(t);return `<button class="publication-card" data-live-task="${h(t.id)}"><div><b>${h(t.title)}</b><p>${h(t.accountName||'账号未提供')} · ${h(t.assignee||'负责人未提供')}</p><small>${h(t.plannedPublishOn||'未排期')}${t.experimentStatus==='concluded'?' · 已结束':''}</small></div><div class="publication-counts"><span><b>${count(p.published)}</b><small>已发布</small></span><span><b>${count(p.filled)}</b><small>已回填</small></span><span><b>${count(p.target)}</b><small>计划数量</small></span></div><span class="task-arrow">›</span></button>`;}).join('')||blank('暂无符合条件的发布事项','这里引用原执行事项，不另建一份发布任务。');};$('#publish-query').oninput=render;$('#publish-scope').onchange=render;render();
 }
 function productTests(products,tasks){
  const rows=tasks.filter(t=>t.sourceType==='product');
  $('#main').innerHTML=pageHeader('测品中心','围绕产品推进测试执行，资料与结果保持关联。')+`<section class="summary-strip"><div><b>${products.filter(p=>p.active).length}</b><span>在用产品</span></div><div><b>${rows.length}</b><span>测品事项</span></div><div><b>${rows.filter(t=>t.completedAt).length}</b><span>有完成事实</span></div></section><section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">搜索测试<input id="product-test-query" type="search" placeholder="事项、产品、账号或负责人"></label><label>按产品<select id="product-test-product"><option value="all">全部产品</option>${products.map(p=>`<option value="${h(p.id)}">${h(p.name)}</option>`).join('')}</select></label></div><div id="product-test-list"></div><div class="module-foot">进度来自现有执行记录，产品是否值得继续测试以复盘结论为准。</div></section>`;
  const render=()=>{const q=$('#product-test-query').value.trim().toLowerCase(),product=$('#product-test-product').value;const visible=rows.filter(t=>(product==='all'||t.productId===product)&&[t.title,t.productName,t.accountName,t.assignee].join(' ').toLowerCase().includes(q));$('#product-test-list').innerHTML=visible.map(t=>`<article class="product-test-row"><div><span class="type-tag">${h(t.stageName||'测试执行')}</span><button class="table-title" data-live-task="${h(t.id)}">${h(t.title)}</button><p class="muted">${h(t.productName||'产品未提供')} · ${h(t.accountName||'无需账号')} · ${h(t.assignee||'负责人未提供')}</p></div><div>${t.productId?`<button class="text-button" data-product-detail="${h(t.productId)}">产品档案 →</button>`:''}<p class="muted">${h(taskProgress(t))}</p></div></article>`).join('')||blank('暂无符合条件的测品事项','产品档案与测试执行保持分开，后续安排会进入同一队列。');};$('#product-test-query').oninput=render;$('#product-test-product').onchange=render;render();
 }
 return {shootingDetail,async render(page,signal,user){
  canEditProducts=writable&&user.role==='admin';
  if(page==='products'){const rows=await api.products(signal);if(!signal.aborted)catalog(rows);}
  if(page==='shooting'){const rows=await api.shooting(signal);if(!signal.aborted)shooting(rows);}
  if(page==='calendar'||page==='publishing'){const rows=await api.workTasks(signal);if(!signal.aborted)page==='calendar'?calendar(rows,user):publishing(rows);}
  if(page==='product-tests'){const [products,tasks]=await Promise.all([api.products(signal),api.workTasks(signal)]);if(!signal.aborted)productTests(products,tasks);}
 }};
}
